import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun bad(userId: String) {
        val sb = StringBuilder().append("User: ").append(userId)
        log.debug(sb.toString())
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun bad2(item: String) {
        val msg = StringBuilder("Processing ").append(item).toString()
        log.trace(msg)
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(userId: String) {
        log.debug("User: {}", userId)
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good2(item: String) {
        if (log.isDebugEnabled) {
            log.debug("Processing: $item")
        }
    }
}
